1180	export function patternRule(declaration, { selfExclude = null } = {}) {
1181	  const where = `the declared check "${declaration.id}"`;
1182	  if (typeof declaration.id !== 'string' || !declaration.id.trim()) {
1183	    throw new Error('a declared check needs a non-empty "id"');
1184	  }
1185	  if (declaration.severity !== 'blocking' && declaration.severity !== 'advisory') {
1186	    throw new Error(`${where}: severity must be "blocking" or "advisory", not ${JSON.stringify(declaration.severity)}`);
1187	  }
1188	  validateSpecKeys(declaration, 'spec', where);
1189	  const spec = compileSpec(declaration, null, where);
1190	  normalizeLegacySpellings(spec);
1191	  validateEntryShapes(spec, where);
1192	  const classPatterns = (names) => (names ?? []).map((n) => {
1193	    if (!FILE_CLASSES[n]) {
1194	      throw new Error(`${where}: "${n}" is not a file class — the classes are: ${Object.keys(FILE_CLASSES).join(', ')}`);
1195	    }
1196	    return FILE_CLASSES[n];
1197	  });
1198	  const scanClasses = classPatterns(spec.scanFileClasses);
1199	  if (scanClasses.length && typeof spec.scanFiles === 'string') {
1200	    throw new Error(`${where}: scanFileClasses cannot combine with an exact-path scanFiles`);
1201	  }
1202	  // The normalized selection surface the scan reads: the sweep patterns
1203	  // (regex scanFiles + classes) and every exclusion (declared, class-named,
1204	  // and the loader-supplied self-exclusion) as flat lists.
1205	  spec.scanMatchers = [...(spec.scanFiles instanceof RegExp ? [spec.scanFiles] : []), ...scanClasses];
1206	  spec.excludeMatchers = [
1207	    ...(spec.excludeFiles != null ? [spec.excludeFiles] : []),
1208	    ...classPatterns(spec.excludeFileClasses),
1209	    ...(selfExclude ? [selfExclude] : []),
1210	  ];
1211	  if (typeof spec.fix === 'string') applyFixDefault(spec, spec.fix);
1212	  if (spec.forbidReferences !== undefined) {
1213	    const { edges, errors } = normalizeEdges(spec.forbidReferences);
1214	    if (errors.length) throw new Error(`${where}: ${errors[0].what} — ${errors[0].fix}`);
1215	    spec.edges = edges;
1216	  }
1217	  const rule = {
1218	    id: spec.id,
1219	    severity: spec.severity,
1220	    why: spec.failureMessage,
1221	    spec,
1222	    run(ctx) { return results(ctx).get(rule); },
1223	  };
1224	  REGISTRY.push(rule);
1225	  return rule;
1226	}
