1228	// A directory's declared checks: `<dir>/declared-checks.json`, an array of specs
1229	// compiled into rules — none when the file is absent. Cached by path, so the
1230	// registry and a test asking the same directory share one set of rule objects
1231	// (two would each re-run the shared scan for the same assertions).
1232	//
1233	// A SKILL's declarations (a dir named `…/skills/<name>`) are compiled with a
1234	// structural self-exclusion — content under any `skills/<name>/` path segment
1235	// pair is out of every assertion's scope — so a skill's own SKILL.md examples
1236	// never trip its checks, in whichever tree the skill's content appears (the
1237	// canon's packs/<pack>/skills/, a root skills/ layout, a consumer's mounted
1238	// .claude/skills/ links), without each declaration hand-spelling the exclusion.
1239	const loaded = new Map();
1240	export function loadDeclaredChecks(dir) {
1241	  const path = join(dir, 'declared-checks.json');
1242	  if (!loaded.has(path)) {
1243	    let specs = [];
