 *     },
 *     flagged: {
 *       'the hazard is reported at its line': {
 *         files: { 'a.txt': 'bad\n' },
 *         at: [{ file: 'a.txt', line: 1, what: /bad/ }],
 *       },
 *     },
 *   });
 *
